int le_backend_init(struct le_backend **out,const char *mode,const char *mock,const char *cfg,unsigned seed){struct le_backend*b;if(!out)return LE_INVALID;b=calloc(1,sizeof(*b));if(!b)return LE_IO;strncpy(b->mode,mode?mode:"mock",15);if((!strcmp(b->mode,"mock")?le_mock_create(b,mock,cfg,seed):!strcmp(b->mode,"linux")?le_linux_create(b,cfg):LE_INVALID)!=LE_OK){free(b);return LE_INVALID;}*out=b;return LE_OK;}
void le_backend_destroy(struct le_backend*b){if(b){if(b->ops&&b->ops->destroy)b->ops->destroy(b);free(b);}}
const char*le_backend_mode(struct le_backend*b){return b?b->mode:"unknown";}
const char*le_result_code(int r){switch(r){case LE_INVALID:return"invalid_request";case LE_NOT_SUPPORTED:return"not_supported";case LE_IO:return"io_error";case LE_BUSY:return"busy";case LE_AUTH:return"forbidden";default:return"internal_error";}}
